"""Checks the Python verifier against signature vectors generated by the relay.

CI sets VECTORS to a file the relay produced in the same job; locally the committed copy is used.
"""

import base64
import json
import os
import unittest

from standard_webhooks import verify

VECTORS = os.environ.get("VECTORS", os.path.join(os.path.dirname(__file__), "..", "vectors", "signature-vectors.json"))


class RelayVectorTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        with open(VECTORS, encoding="utf-8") as f:
            data = json.load(f)
        cls.vectors = data["vectors"]
        cls.tolerance = data["toleranceSeconds"]

    def test_vectors_cover_both_outcomes(self):
        self.assertTrue(any(v["expectValid"] for v in self.vectors))
        self.assertTrue(any(not v["expectValid"] for v in self.vectors))

    def test_every_vector(self):
        for v in self.vectors:
            with self.subTest(v["name"]):
                ok = verify(
                    v["receiverSecrets"],
                    v["webhookId"],
                    v["webhookTimestamp"],
                    v["webhookSignature"],
                    base64.b64decode(v["bodyBase64"]),
                    now=v["now"],
                    tolerance_seconds=self.tolerance,
                )
                self.assertEqual(ok, v["expectValid"])


if __name__ == "__main__":
    unittest.main()
